"""Product Analyzer - uses OpenRouter AI to analyze uploaded products."""

import json
import logging
from dataclasses import dataclass, field
from typing import Optional

import httpx
from pydantic import BaseModel

from src.sales_engine.core.config import settings

logger = logging.getLogger(__name__)


class ProductInfo(BaseModel):
    """Complete product information generated by AI."""

    name: str
    description: str
    category: str
    buyer_persona: str
    keywords: list[str] = field(default_factory=list)
    search_queries: list[str] = field(default_factory=list)
    platform_descriptions: dict[str, str] = field(default_factory=dict)


class FileAnalysis(BaseModel):
    """Result of analyzing a product file."""

    file_name: str
    file_type: str
    extracted_text: Optional[str] = None
    product_info: Optional[ProductInfo] = None
    error: Optional[str] = None


class ProductAnalyzer:
    """Analyzes uploaded product files using OpenRouter AI."""

    def __init__(self) -> None:
        self.api_key = settings.openrouter_api_key
        self.base_url = f"{settings.openrouter_base_url}/chat/completions"

    async def analyze_product(self, file_path: str, file_type: str) -> FileAnalysis:
        """Analyze a product file and extract all information needed for distribution."""
        try:
            extracted_text = self._extract_text(file_path, file_type)
            product_info = await self._generate_product_info(extracted_text, file_type)

            return FileAnalysis(
                file_name=file_path,
                file_type=file_type,
                extracted_text=extracted_text,
                product_info=product_info,
            )
        except Exception as e:
            logger.error("Failed to analyze product: %s", e)
            return FileAnalysis(
                file_name=file_path,
                file_type=file_type,
                extracted_text=None,
                error=str(e),
            )

    def _extract_text(self, file_path: str, file_type: str) -> Optional[str]:
        """Extract text from uploaded file."""
        # For now, return placeholder. In production, use:
        # pdfplumber for PDFs, python-docx for docs, etc.
        return f"Product file: {file_path} ({file_type})"

    async def _generate_product_info(
        self, text: Optional[str], file_type: str
    ) -> Optional[ProductInfo]:
        """Use OpenRouter AI to generate complete product information."""
        if not self.api_key:
            logger.warning("No OpenRouter API key configured")
            return None

        prompt = self._build_prompt(text, file_type)

        try:
            async with httpx.AsyncClient() as client:
                response = await client.post(
                    self.base_url,
                    headers={
                        "Authorization": f"Bearer {self.api_key}",
                        "Content-Type": "application/json",
                        "HTTP-Referer": "http://localhost:3000",
                        "X-Title": "Sales Engine",
                    },
                    json={
                        "model": settings.openrouter_model,
                        "messages": [
                            {"role": "system", "content": self._get_system_prompt()},
                            {"role": "user", "content": prompt},
                        ],
                        "temperature": 0.7,
                    },
                    timeout=60.0,
                )
                response.raise_for_status()
                data = response.json()
                content = data["choices"][0]["message"]["content"]

                # Parse JSON from response
                if "```json" in content:
                    content = content.split("```json")[1].split("```")[0]
                elif "```" in content:
                    content = content.split("```")[1].split("```")[0]

                return ProductInfo.model_validate_json(content.strip())
        except Exception as e:
            logger.error("AI product analysis failed: %s", e)
            return None

    def _build_prompt(self, text: Optional[str], file_type: str) -> str:
        """Build the AI prompt for product analysis."""
        return f"""Analyze this product file:

File type: {file_type}
Content: {text or "Binary file - analyze based on context"}

Generate a complete JSON object with:
- name: Product name (catchy, clear, 3-6 words)
- description: Full product description (what it does, who it helps, 2-3 sentences)
- category: Product category (e.g., "Notion Templates", "Python Scripts", "Design Assets", "Marketing Tools", "Courses", "SaaS Tools")
- buyer_persona: Who is the ideal buyer? (e.g., "Freelancers tracking client work", "Marketers managing campaigns", "Students organizing notes")
- keywords: 20+ keywords people would search for (single words and short phrases)
- search_queries: 15+ natural search phrases buyers would type
- platform_descriptions: Object with platform-specific descriptions:
  - gumroad: Description optimized for Gumroad marketplace (casual, creator voice, 2-3 sentences)
  - lemonsqueezy: Description optimized for Lemon Squeezy
  - alternativeto: Description for AlternativeTo listing (what it is vs competitors)
  - indiehackers: Description for IndieHackers (maker voice, startup angle)
  - odoo: Description for Odoo App Store (if relevant to Odoo ecosystem)
  - producthunt: Description for Product Hunt launch (compelling, 1-2 sentences)

Output ONLY valid JSON, no markdown formatting, no explanation."""

    def _get_system_prompt(self) -> str:
        return """You are a product analyst specializing in digital products. You extract comprehensive information about digital products to help them get discovered across multiple platforms. Always output valid JSON with all fields."""
